include <robotics.scad>
// Molicel INR-18650-P28A wrapped can. Local origin: cell centre, axis +Z = positive end.
// Datasheet: Ø18.6 max, height 65.2 max (terminal to base).
D = 18.6;        // max diameter, datasheet
H = 65.2;        // max height incl. positive cap, datasheet
cap_h = 0.5;     // undimensioned: conservative cap protrusion, kept inside H
body_h = H - cap_h;
edge = 0.6;      // undimensioned end-edge softening (stays inside envelope)
seat_d = 7.2; seat_depth = 0.2;   // seat for the cap disc (cap Ø7 + clearance)
difference() {
  down(H/2) cyl(d = D, h = body_h, rounding = edge, anchor = BOT, $fn = 96);
  up(H/2 - cap_h - seat_depth) cyl(d = seat_d, h = 1, anchor = BOT, $fn = 64);
}

include <robotics.scad>
// Positive terminal cap. Not dimensioned by Molicel: plain, conservative disc.
// Local origin: cap base (seated 0.2 mm into the can), +Z outward. Top face lands at H = 65.2.
cap_d = 7;     // undimensioned placeholder
cap_h = 0.7;   // 0.2 seated + 0.5 proud; top at 65.2 max height
cyl(d = cap_d, h = cap_h, chamfer2 = 0.2, anchor = BOT, $fn = 64);
